import sys

def main():
    limit = 2005
    MOD = 1000000007
    table = [[0] * limit for _ in range(limit)]
    visited = [[0] * limit for _ in range(limit)]
    visited[0][0] = 1

    for i in range(1, limit):
        for j in range(i & 1, i + 1, 2):
            if j == 0:
                table[i][j] = table[i - 1][j + 1]
                if visited[i - 1][j + 1] == 1:
                    table[i][j] = (table[i][j] + 1) % MOD
                else:
                    visited[i][j] = 1
                continue
            table[i][j] = (table[i - 1][j - 1] + table[i - 1][j + 1]) % MOD
            if visited[i - 1][j + 1] == 1 or visited[i - 1][j - 1] == 1:
                table[i][j] = (table[i][j] + 1) % MOD
            else:
                visited[i][j] = 1

    input_number = int(sys.stdin.read())
    print(table[2 * input_number][0])

if __name__ == "__main__":
    main()

